modules.identifiers.ubnf:
grammar Identifiers {
  @import chars from 'characters.ubnf'
  @ubnf: v2
  token IDENTIFIER ::= chars.LETTER (chars.LETTER | chars.DIGIT)*;
  token CLASS_NAME ::= IDENTIFIER ('.' IDENTIFIER)*;
}

modules.numbers.ubnf:
grammar Numbers {
  @import chars from 'characters.ubnf'
  @ubnf: v2
  // Optional sign, integer/fraction, optional complete exponent. No implicit trivia.
  token NUMBER ::= ['+' | '-']
    (chars.DIGIT+ '.' chars.DIGIT* | '.' chars.DIGIT+ | chars.DIGIT+)
    [('e' | 'E') ['+' | '-'] chars.DIGIT+];
}

modules.fences.ubnf:
grammar Fences {
  @import chars from 'characters.ubnf'
  @import names from 'identifiers.ubnf'
  @ubnf: v2
  // The legacy three-backtick form ends at its first triple-backtick sequence.
  token CODE_START ::= BOL '```' names.IDENTIFIER ':' names.CLASS_NAME (chars.NEWLINE | EOF);
  token CODE_BODY ::= { NEGATIVE_LOOKAHEAD('```') ANY } LOOKAHEAD('```');
  token CODE_END ::= BOL '```' (chars.NEWLINE | EOF);
  // Four or more backticks: closing width must equal the captured opening width.
  // A shorter/longer fence or a non-standalone line remains opaque body text.
  token LONG_CODE_BLOCK ::= BOL CAPTURE(fence, '`'{4,}) names.IDENTIFIER ':' names.CLASS_NAME chars.NEWLINE
    { NEGATIVE_LOOKAHEAD(BOL SAME_AS(fence) EOL) ANY }
    BOL SAME_AS(fence) (chars.NEWLINE | EOF);
}

modules.strings.ubnf:
grammar Strings {
  @ubnf: v2
  // Quotes and escape pairs are raw source, including newlines and non-BMP scalars.
  // AST normalization belongs to the consumer, not this recognizer.
  token STRING ::= '"' { '\\' ANY | NEGATION('"\\') } '"'
                 | '\'' { '\\' ANY | NEGATION('\'\\') } '\'';
}

modules.characters.ubnf:
grammar Characters {
  @ubnf: v2
  token DIGIT ::= CHAR_RANGE('0', '9');
  token LETTER ::= CHAR_RANGE('a', 'z') | CHAR_RANGE('A', 'Z') | '_';
  token NEWLINE ::= '\r\n' | '\r' | '\n';
}

